<?php
$dash='—';
$display=function($value)use($dash){$value=trim((string)$value);return$value===''?$dash:$value;};
$orderReference=$display($o['customer_order_reference']??$s['_order']['customer_order']??'');
$articleReference=$display($o['article_code']?:($s['customer_product_code']??$s['code']??''));
$description=$display($o['article_description']?:($s['description']??''));
$dimensions=array_filter([trim((string)($s['width']??'')),trim((string)($s['length']??''))],'strlen');
$dimensions=$dimensions?implode(' × ',$dimensions):$dash;
$quantity=pd_num($o['planned_quantity']);
$quantityUnit=trim((string)($s['unit_code']??$s['unit']??''));if($quantityUnit!=='')$quantity.=' '.$quantityUnit;
$printerRoll=$display($s['printer_roll_measure']??'');
if($printerRoll!==$dash&&!preg_match('/^rolo\b/iu',$printerRoll))$printerRoll='Rolo de '.$printerRoll;
?>
